insert into public.profiles (id, phone_hash, name, last_name, birthdate, neighborhood, cover, avatar_path, intro_quote, lyric_quote, taste, style_paths, seeking, details, prompts, onboarded, created_at) values
  ('00000000-0000-4000-8000-000000000201', encode(sha256('+15550002001'::bytea), 'hex'), 'Marcus', 'Reid', '1998-06-14', 'Harlem', 'stripes', 'demo/people/marcus.jpg', 'Golden hour or nothing.', 'Dreams of money trees.', '{collector,nostalgic}', '{demo/stickers/headphones.png,demo/album-2.png}', 'crush', '{"hometown": "Philadelphia", "location": "Harlem", "gender": "Man", "occupation": "Photographer", "education": "Undergrad", "height": "6′0", "activity": "Active", "kids": "Not sure yet", "drinking": "Socially", "smoking": "No"}', '{"intro": {"text": "Golden hour or nothing."}, "lyrics": {"text": "Dreams of money trees."}, "obsession": {"text": "Shooting strangers on 35mm."}, "dealbreakers": {"text": "Walking slow on a busy sidewalk."}}', true, now() - interval '7 minutes'),
  ('00000000-0000-4000-8000-000000000202', encode(sha256('+15550002002'::bytea), 'hex'), 'Kwame', 'Asante', '2000-02-03', 'Bed-Stuy', 'discs', 'demo/people/kwame.jpg', 'Paint on my hands, Afrobeats in my ears.', 'Last last, na everybody go chop breakfast.', '{live_shows,all_around}', '{demo/gifs/dancing-men.gif,demo/stickers/sticker-sneakers.png}', 'casual', '{"hometown": "Accra", "location": "Bed-Stuy", "gender": "Man", "occupation": "Muralist", "education": "Art school", "height": "6′2", "activity": "Very active", "kids": "Not sure yet", "drinking": "Socially", "smoking": "No"}', '{"intro": {"text": "Paint on my hands, Afrobeats in my ears."}, "lyrics": {"text": "Last last, na everybody go chop breakfast."}, "obsession": {"text": "Finding walls nobody has painted yet."}, "dealbreakers": {"text": "No dancing at a wedding."}}', true, now() - interval '14 minutes'),
  ('00000000-0000-4000-8000-000000000203', encode(sha256('+15550002003'::bytea), 'hex'), 'Sofia', 'Marín', '2001-09-21', 'Williamsburg', 'holo', 'demo/people/sofia.jpg', 'Thrifted everything, including my opinions.', 'Qué rico sería, pero ahora no.', '{nostalgic,classics}', '{demo/stickers/sticker-cocktail.png,demo/album-4.png}', 'crush', '{"hometown": "Miami", "location": "Williamsburg", "gender": "Woman", "occupation": "Stylist", "education": "Undergrad", "height": "5′6", "activity": "Sometimes active", "kids": "Doesn’t want kids", "drinking": "Socially", "smoking": "Socially"}', '{"intro": {"text": "Thrifted everything, including my opinions."}, "lyrics": {"text": "Qué rico sería, pero ahora no."}, "obsession": {"text": "Mexican pastries at 8am."}, "dealbreakers": {"text": "Socks with sandals, unironically."}}', true, now() - interval '21 minutes'),
  ('00000000-0000-4000-8000-000000000204', encode(sha256('+15550002004'::bytea), 'hex'), 'Arjun', 'Mehta', '1997-11-08', 'Long Island City', 'reeded', 'demo/people/arjun.jpg', 'Building things, mostly playlists.', 'I’m not the kind of guy to take it slow.', '{audiophile,all_around}', '{demo/album-1.png,demo/stickers/headphones.png}', 'serious', '{"hometown": "Chicago", "location": "Long Island City", "gender": "Man", "occupation": "Architect", "education": "Graduate", "height": "5′11", "activity": "Active", "kids": "Wants kids", "drinking": "Drinks", "smoking": "No"}', '{"intro": {"text": "Building things, mostly playlists."}, "lyrics": {"text": "I’m not the kind of guy to take it slow."}, "obsession": {"text": "Brutalist buildings and soft synths."}, "dealbreakers": {"text": "Leaving a voice note longer than a minute."}}', true, now() - interval '28 minutes'),
  ('00000000-0000-4000-8000-000000000205', encode(sha256('+15550002005'::bytea), 'hex'), 'June', 'Holt', '2002-04-17', 'Ridgewood', 'reeded-warm', 'demo/people/june.jpg', 'I made your favorite mug, probably.', 'I’m wide awake, there’s a kid in my head.', '{collector,nostalgic}', '{demo/stickers/sticker-coffee.png,demo/gifs/black-cat.gif}', 'friends', '{"hometown": "Portland", "location": "Ridgewood", "gender": "Woman", "occupation": "Ceramicist", "education": "Art school", "height": "5′5", "activity": "Sometimes active", "kids": "Not sure yet", "drinking": "Socially", "smoking": "No"}', '{"intro": {"text": "I made your favorite mug, probably."}, "lyrics": {"text": "I’m wide awake, there’s a kid in my head."}, "obsession": {"text": "Mitski at full volume in the kiln room."}, "dealbreakers": {"text": "Not crying at the end of a movie."}}', true, now() - interval '35 minutes'),
  ('00000000-0000-4000-8000-000000000206', encode(sha256('+15550002006'::bytea), 'hex'), 'Camille', 'Durand', '1998-01-29', 'Carroll Gardens', 'rain', 'demo/people/camille.jpg', 'Wine, trench coats, and too many tabs open.', 'It’s you, it’s you, it’s all for you.', '{classics,nostalgic}', '{demo/stickers/sticker-cloche.png,demo/album-3.png}', 'longterm', '{"hometown": "Montréal", "location": "Carroll Gardens", "gender": "Woman", "occupation": "Copywriter", "education": "Graduate", "height": "5′8", "activity": "Moderately active", "kids": "Wants kids", "drinking": "Drinks", "smoking": "No"}', '{"intro": {"text": "Wine, trench coats, and too many tabs open."}, "lyrics": {"text": "It’s you, it’s you, it’s all for you."}, "obsession": {"text": "Old French films with no subtitles."}, "dealbreakers": {"text": "People who don’t return library books."}}', true, now() - interval '42 minutes'),
  ('00000000-0000-4000-8000-000000000207', encode(sha256('+15550002007'::bytea), 'hex'), 'Rafa', 'Ortiz', '1996-07-02', 'Bushwick', 'waveform', 'demo/people/rafa.jpg', 'Ask me about my worst tattoo.', 'Turn it up, I wanna feel it.', '{live_shows,collector}', '{demo/stickers/guitar.png,demo/stickers/ticket.png}', 'casual', '{"hometown": "San Juan", "location": "Bushwick", "gender": "Man", "occupation": "Tattoo artist", "education": "High school", "height": "5′10", "activity": "Active", "kids": "Doesn’t want kids", "drinking": "Drinks", "smoking": "Socially"}', '{"intro": {"text": "Ask me about my worst tattoo."}, "lyrics": {"text": "Turn it up, I wanna feel it."}, "obsession": {"text": "Hardcore shows on a Tuesday."}, "dealbreakers": {"text": "Not tipping your bartender."}}', true, now() - interval '49 minutes'),
  ('00000000-0000-4000-8000-000000000208', encode(sha256('+15550002008'::bytea), 'hex'), 'Leo', 'Brandt', '1998-03-11', 'Lower East Side', 'vinyl', 'demo/people/leo.jpg', 'I’ll cook, you pick the music.', 'We lost track of time.', '{live_shows,audiophile}', '{demo/gifs/disco.gif,demo/stickers/sticker-pizza.png}', 'crush', '{"hometown": "Berlin", "location": "Lower East Side", "gender": "Man", "occupation": "Line cook", "education": "Culinary school", "height": "6′1", "activity": "Active", "kids": "Not sure yet", "drinking": "Drinks", "smoking": "No"}', '{"intro": {"text": "I’ll cook, you pick the music."}, "lyrics": {"text": "We lost track of time."}, "obsession": {"text": "Warehouse sets that end at sunrise."}, "dealbreakers": {"text": "Ketchup on eggs."}}', true, now() - interval '56 minutes'),
  ('00000000-0000-4000-8000-000000000209', encode(sha256('+15550002009'::bytea), 'hex'), 'Ivy', 'Callahan', '2000-10-05', 'East Village', 'holo', 'demo/people/ivy.jpg', 'Born in the wrong decade, dressed for it anyway.', 'Thunder only happens when it’s raining.', '{nostalgic,classics}', '{demo/stickers/heart.png,demo/album-5.png}', 'casual', '{"hometown": "Austin", "location": "East Village", "gender": "Woman", "occupation": "Vintage buyer", "education": "Undergrad", "height": "5′7", "activity": "Sometimes active", "kids": "Not sure yet", "drinking": "Socially", "smoking": "Socially"}', '{"intro": {"text": "Born in the wrong decade, dressed for it anyway."}, "lyrics": {"text": "Thunder only happens when it’s raining."}, "obsession": {"text": "Flea markets before 7am."}, "dealbreakers": {"text": "Fast fashion hauls."}}', true, now() - interval '63 minutes'),
  ('00000000-0000-4000-8000-000000000210', encode(sha256('+15550002010'::bytea), 'hex'), 'Amara', 'Okafor', '1999-05-26', 'Crown Heights', 'discs', 'demo/people/amara.jpg', 'If the song is good I’m dancing, wherever.', 'Good days in my mind.', '{all_around,live_shows}', '{demo/gifs/spinning-dancer.gif,demo/stickers/note.png}', 'serious', '{"hometown": "Houston", "location": "Crown Heights", "gender": "Woman", "occupation": "Dancer", "education": "Undergrad", "height": "5′6", "activity": "Very active", "kids": "Wants kids", "drinking": "Socially", "smoking": "No"}', '{"intro": {"text": "If the song is good I’m dancing, wherever."}, "lyrics": {"text": "Good days in my mind."}, "obsession": {"text": "Choreographing to voice memos."}, "dealbreakers": {"text": "Not standing up for the encore."}}', true, now() - interval '70 minutes'),
  ('00000000-0000-4000-8000-000000000211', encode(sha256('+15550002011'::bytea), 'hex'), 'Zuri', 'Lawson', '2001-12-12', 'Fort Greene', 'rain', 'demo/people/zuri.jpg', 'Ask me about bike lanes, I dare you.', 'Don’t you wanna dance with me?', '{audiophile,classics}', '{demo/album-2.png,demo/stickers/sticker-coffee.png}', 'friends', '{"hometown": "Oakland", "location": "Fort Greene", "gender": "Woman", "occupation": "Grad student, urban planning", "education": "Graduate", "height": "5′9", "activity": "Moderately active", "kids": "Not sure yet", "drinking": "Rarely", "smoking": "No"}', '{"intro": {"text": "Ask me about bike lanes, I dare you."}, "lyrics": {"text": "Don’t you wanna dance with me?"}, "obsession": {"text": "Neo-soul records from my dad’s shelf."}, "dealbreakers": {"text": "Saying “it is what it is” in an argument."}}', true, now() - interval '77 minutes'),
  ('00000000-0000-4000-8000-000000000212', encode(sha256('+15550002012'::bytea), 'hex'), 'Nia', 'Brooks', '1997-08-19', 'Clinton Hill', 'waveform', 'demo/people/nia.jpg', 'I pick the songs in the shows you binge.', 'I was good on my own, that’s the way it was.', '{live_shows,all_around}', '{demo/stickers/ticket-sm.png,demo/gifs/heart.gif}', 'crush', '{"hometown": "Brooklyn", "location": "Clinton Hill", "gender": "Woman", "occupation": "Music supervisor", "education": "Undergrad", "height": "5′5", "activity": "Active", "kids": "Not sure yet", "drinking": "Drinks", "smoking": "No"}', '{"intro": {"text": "I pick the songs in the shows you binge."}, "lyrics": {"text": "I was good on my own, that’s the way it was."}, "obsession": {"text": "Finding the perfect song for a montage."}, "dealbreakers": {"text": "Skipping songs before the bridge."}}', true, now() - interval '84 minutes'),
  ('00000000-0000-4000-8000-000000000213', encode(sha256('+15550002013'::bytea), 'hex'), 'Finn', 'O’Connor', '2002-01-24', 'Greenpoint', 'stripes', 'demo/people/finn.jpg', 'Pulling shots by day, playing bass by night.', 'Where is my mind?', '{classics,collector}', '{demo/stickers/guitar.png,demo/album-3.png}', 'casual', '{"hometown": "Dublin", "location": "Greenpoint", "gender": "Man", "occupation": "Barista and bassist", "education": "Some college", "height": "5′10", "activity": "Sometimes active", "kids": "Doesn’t want kids", "drinking": "Drinks", "smoking": "Socially"}', '{"intro": {"text": "Pulling shots by day, playing bass by night."}, "lyrics": {"text": "Where is my mind?"}, "obsession": {"text": "Rolling Stones bootlegs."}, "dealbreakers": {"text": "Oat milk snobs. (I’m one.)"}}', true, now() - interval '91 minutes'),
  ('00000000-0000-4000-8000-000000000214', encode(sha256('+15550002014'::bytea), 'hex'), 'Kai', 'Nakamura', '2000-06-30', 'Astoria', 'reeded-warm', 'demo/people/kai.jpg', 'Teaching kids to skate, still falling myself.', 'Don’t leave, it’s my fault.', '{all_around,nostalgic}', '{demo/stickers/sticker-sneakers.png,demo/gifs/thumbs-up.gif}', 'friends', '{"hometown": "Honolulu", "location": "Astoria", "gender": "Man", "occupation": "Skate coach", "education": "Some college", "height": "5′9", "activity": "Very active", "kids": "Not sure yet", "drinking": "Rarely", "smoking": "No"}', '{"intro": {"text": "Teaching kids to skate, still falling myself."}, "lyrics": {"text": "Don’t leave, it’s my fault."}, "obsession": {"text": "Perfecting a kickflip at 27."}, "dealbreakers": {"text": "Not sharing fries."}}', true, now() - interval '98 minutes')
