-- Sync: fourteen more people for the feed (photos the user picked, in sync/assets/people/; the app maps demo/ to assets/).
-- Fictional people on stock photos, for testing. Each has a mixtape with real covers, prompts, details, spots,
-- watching & reading, and a stand-in that answers on their own. Safe to re-run.

on conflict (id) do nothing;

on conflict (id) do update set name = excluded.name, last_name = excluded.last_name, birthdate = excluded.birthdate, neighborhood = excluded.neighborhood, cover = excluded.cover, avatar_path = excluded.avatar_path,
  intro_quote = excluded.intro_quote, lyric_quote = excluded.lyric_quote, taste = excluded.taste, style_paths = excluded.style_paths, seeking = excluded.seeking, details = excluded.details, prompts = excluded.prompts, onboarded = true;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict do nothing;

on conflict (profile_id, key) do nothing;

on conflict (id) do update set items = excluded.items;

on conflict (profile_id) do update set pace = excluded.pace, lines = excluded.lines;
